uint16_t sky_saved_aspect_width(const std::string& path) {
    int aspect = 2; // SkySettingsState defaults to 16:9.
    if (!path.empty()) {
        std::ifstream in(path);
        std::string line;
        while (std::getline(in, line)) {
            const size_t eq = line.find('=');
            if (eq == std::string::npos) continue;
            std::string key = line.substr(0, eq);
            const size_t first = key.find_first_not_of(" \t\r");
            const size_t last = key.find_last_not_of(" \t\r");
            if (first == std::string::npos) continue;
            key = key.substr(first, last - first + 1);
            if (key == "aspect_ratio") {
                aspect = std::clamp(std::atoi(line.c_str() + eq + 1), 0, 3);
                break;
            }
        }
    }
    static constexpr uint16_t kWidths[4] = {256, 308, 342, 448};
    return kWidths[aspect];
}

int nds_run_interactive_frontend(const NdsFrontendOptions& initial_options) {
    NdsFrontendOptions options = initial_options;
    // Title-owned adaptive widescreen is enabled only for the two verified
    // PMD Sky revisions. Config-level `adaptive_capability` would require a
    // single exact game.sha1, which would reject the other region.
    const std::string& rom_sha1 = !options.savestate_rom_sha1.empty()
        ? options.savestate_rom_sha1 : options.expected_rom_sha1;
    const bool pmd_sky_rom =
        rom_sha1 == "5fa96ca8d8dd6405d6cd2bad73ed68bc73a9d152" ||
        rom_sha1 == "c838a5adf1ed32d2da8454976e5b1a1aa189c139";
    if (pmd_sky_rom) {
        options.adaptive_supported = NDS_ADAPTIVE_TOP;
        const uint16_t saved_width =
            sky_saved_aspect_width(options.runtime_settings_path);
        if (saved_width > 256) {
            options.adaptive_screens = NDS_ADAPTIVE_TOP;
            options.adaptive_max_width[0] = saved_width;
        } else {
            options.adaptive_screens = NDS_ADAPTIVE_NONE;
        }
        options.adaptive_hud_anchor = true;
        nds_gpu2d_set_adaptive_hud_anchor(true,
                                          options.adaptive_hud_center_width);
    }
    if (options.adaptive_screens & NDS_ADAPTIVE_TOP) {
        const uint16_t requested_width =
            std::max<uint16_t>(options.adaptive_max_width[0], 256);
        if (!nds_gpu3d_set_output_width(requested_width)) {
            std::fprintf(stderr,
                         "[sdl] adaptive width %u unavailable; using native "
                         "256px instead\n",
                         static_cast<unsigned>(requested_width));
            options.adaptive_screens = NDS_ADAPTIVE_NONE;
            options.adaptive_max_width[0] = 256;
            options.adaptive_max_width[1] = 256;
