patches = [
    'macos-arm64', 'msvc-tools', 'window-title', 'sky-settings-overlay',
    'sky-widescreen', 'sky-static-pictures', 'ios', 'ios-touch',
]
with tempfile.TemporaryDirectory() as directory:
    root = Path(directory)
    paths = set()
    for name in patches:
        patch = repo / 'patches' / f'ndsrecomp-{name}.patch'
        for line in patch.read_text().splitlines():
            if line.startswith('--- a/'):
                paths.add(line.removeprefix('--- a/'))
    for path in paths:
        dest = root / path
        dest.parent.mkdir(parents=True, exist_ok=True)
