        const uint8_t active = bg_active_mask(u, false);
        for (int bg = 0; bg < 4; ++bg)
            if (active & (1u << bg)) active_bgs[bg_count++] = bg;
    }
    // Front-first order: lower BGCNT priority wins, ties break to the lower
