    u.refy_internal[affine] += u.pd[affine];
}

void setup_affine_output(const Unit& u, int bg, BgLine& out) {
    out.prio = static_cast<uint8_t>(u.bgcnt[bg] & 3u);
    out.target = static_cast<uint8_t>(1u << bg);
    out.order = static_cast<uint8_t>(bg + 1);
    out.color.fill(0u);
}

void decode_affine_line(const Unit& u, int engine, int bg, int y,
                        const uint8_t* palette,
                        const NdsVramRendererView& vram, BgLine& out) {
    const uint16_t cnt = u.bgcnt[bg];
    setup_affine_output(u, bg, out);

    uint32_t coordmask = 0;
    uint32_t yshift = 0;
    switch (cnt & 0xC000u) {
        case 0x0000u: coordmask = 0x07800u; yshift = 7; break;
        case 0x4000u: coordmask = 0x0F800u; yshift = 8; break;
        case 0x8000u: coordmask = 0x1F800u; yshift = 9; break;
        default:      coordmask = 0x3F800u; yshift = 10; break;
    }
    const uint32_t overflowmask =
        (cnt & 0x2000u) ? 0u : ~(coordmask | 0x7FFu);
    uint32_t char_base = (cnt & 0x003Cu) << 12;
    uint32_t map_base = (cnt & 0x1F00u) << 3;
    if (!engine) {
        char_base += (u.dispcnt & 0x07000000u) >> 8;
        map_base += (u.dispcnt & 0x38000000u) >> 11;
    }
    yshift -= 3u;

    int32_t line_x = 0;
    int32_t line_y = 0;
    begin_affine_line(u, bg, y, &line_x, &line_y);
    const int affine = bg - 2;
    const int mosaic_width =
        (cnt & 0x0040u) ? static_cast<int>(u.bg_mosaic_x) + 1 : 1;
    for (int x = 0; x < 256; ++x) {
        const int sample_x = x - (x % mosaic_width);
        const int32_t final_x = line_x + sample_x * u.pa[affine];
        const int32_t final_y = line_y + sample_x * u.pc[affine];
        if ((static_cast<uint32_t>(final_x | final_y) & overflowmask) != 0u)
            continue;
        const uint32_t map_addr =
            map_base +
            ((((static_cast<uint32_t>(final_y) & coordmask) >> 11u)
               << yshift) +
             ((static_cast<uint32_t>(final_x) & coordmask) >> 11u));
        const uint8_t tile = bg_view8(vram, engine, map_addr);
        const uint32_t tile_x =
            (static_cast<uint32_t>(final_x) >> 8u) & 7u;
        const uint32_t tile_y =
            (static_cast<uint32_t>(final_y) >> 8u) & 7u;
        const uint8_t index = bg_view8(
            vram, engine,
            char_base + (uint32_t{tile} << 6u) + (tile_y << 3u) + tile_x);
        if (!index) continue;
        out.color[x] = static_cast<uint16_t>(
            view16(palette, uint32_t{index} << 1u) | 0x8000u);
    }
}

void decode_extended_line(const Unit& u, int engine, int bg, int y,
                          const uint8_t* palette,
                          const NdsVramRendererView& vram, BgLine& out) {
    const uint16_t cnt = u.bgcnt[bg];
    setup_affine_output(u, bg, out);

    int32_t line_x = 0;
    int32_t line_y = 0;
    begin_affine_line(u, bg, y, &line_x, &line_y);
    const int affine = bg - 2;
    const int mosaic_width =
        (cnt & 0x0040u) ? static_cast<int>(u.bg_mosaic_x) + 1 : 1;

    if (cnt & 0x0080u) {
        uint32_t xmask = 0, ymask = 0, yshift = 0;
        switch (cnt & 0xC000u) {
            case 0x0000u:
                xmask = ymask = 0x07FFFu; yshift = 7; break;
            case 0x4000u:
                xmask = ymask = 0x0FFFFu; yshift = 8; break;
            case 0x8000u:
                xmask = 0x1FFFFu; ymask = 0x0FFFFu; yshift = 9; break;
            default:
                xmask = ymask = 0x1FFFFu; yshift = 9; break;
        }
        const uint32_t overflow_x = (cnt & 0x2000u) ? 0u : ~xmask;
        const uint32_t overflow_y = (cnt & 0x2000u) ? 0u : ~ymask;
        const uint32_t bitmap_base = (cnt & 0x1F00u) << 6u;
        const bool direct = (cnt & 0x0004u) != 0u;
        for (int x = 0; x < 256; ++x) {
            const int sample_x = x - (x % mosaic_width);
            const int32_t final_x = line_x + sample_x * u.pa[affine];
            const int32_t final_y = line_y + sample_x * u.pc[affine];
            if ((static_cast<uint32_t>(final_x) & overflow_x) ||
                (static_cast<uint32_t>(final_y) & overflow_y))
                continue;
            const uint32_t pixel =
                ((static_cast<uint32_t>(final_y) & ymask) >> 8u) *
                    (1u << yshift) +
                ((static_cast<uint32_t>(final_x) & xmask) >> 8u);
            if (direct) {
                const uint16_t color = bg_view16(
                    vram, engine, bitmap_base + (pixel << 1u));
                if (color & 0x8000u) out.color[x] = color;
            } else {
                const uint8_t index =
                    bg_view8(vram, engine, bitmap_base + pixel);
                if (index)
                    out.color[x] = static_cast<uint16_t>(
                        view16(palette, uint32_t{index} << 1u) | 0x8000u);
            }
        }
        return;
    }

    uint32_t coordmask = 0;
    uint32_t yshift = 0;
    switch (cnt & 0xC000u) {
        case 0x0000u: coordmask = 0x07800u; yshift = 7; break;
        case 0x4000u: coordmask = 0x0F800u; yshift = 8; break;
        case 0x8000u: coordmask = 0x1F800u; yshift = 9; break;
        default:      coordmask = 0x3F800u; yshift = 10; break;
    }
    const uint32_t overflowmask =
        (cnt & 0x2000u) ? 0u : ~(coordmask | 0x7FFu);
    uint32_t char_base = (cnt & 0x003Cu) << 12u;
    uint32_t map_base = (cnt & 0x1F00u) << 3u;
    if (!engine) {
        char_base += (u.dispcnt & 0x07000000u) >> 8u;
        map_base += (u.dispcnt & 0x38000000u) >> 11u;
    }
    const bool extpal = (u.dispcnt & 0x40000000u) != 0u;
    yshift -= 3u;
    for (int x = 0; x < 256; ++x) {
        const int sample_x = x - (x % mosaic_width);
        const int32_t final_x = line_x + sample_x * u.pa[affine];
        const int32_t final_y = line_y + sample_x * u.pc[affine];
        if ((static_cast<uint32_t>(final_x | final_y) & overflowmask) != 0u)
            continue;
        const uint32_t map_addr =
            map_base +
            (((((static_cast<uint32_t>(final_y) & coordmask) >> 11u)
                << yshift) +
              ((static_cast<uint32_t>(final_x) & coordmask) >> 11u))
             << 1u);
        const uint16_t tile = bg_view16(vram, engine, map_addr);
        uint32_t tile_x =
            (static_cast<uint32_t>(final_x) >> 8u) & 7u;
        uint32_t tile_y =
            (static_cast<uint32_t>(final_y) >> 8u) & 7u;
        if (tile & 0x0400u) tile_x = 7u - tile_x;
        if (tile & 0x0800u) tile_y = 7u - tile_y;
        const uint8_t index = bg_view8(
            vram, engine,
            char_base + ((uint32_t{tile} & 0x03FFu) << 6u) +
                (tile_y << 3u) + tile_x);
        if (!index) continue;
        uint16_t color = 0;
        if (extpal) {
            color = static_cast<uint16_t>(nds_vram_read_bg_extpal(
                engine,
                (static_cast<uint32_t>(bg) << 13u) +
                    (static_cast<uint32_t>(tile >> 12u) << 9u) +
                    (uint32_t{index} << 1u),
                2));
        } else {
            color = view16(palette, uint32_t{index} << 1u);
        }
        out.color[x] = static_cast<uint16_t>(color | 0x8000u);
    }
}

void decode_bg_line(const Unit& u, int engine, int bg, int y,
                    const uint8_t* palette,
                    const NdsVramRendererView& vram, BgLine& out) {
    switch (bg_kind(u, bg)) {
        case BgKind::Text:
            decode_text_line(u, engine, bg, y, palette, vram, out);
            break;
    if (top.alpha5) {
        // 3D layer on top: whenever the pixel behind is a BLDCNT second
        // target, per-pixel 5-bit blending is forced regardless of the
        // selected color effect (melonDS ColorComposite coloreffect=4).
        if (u.bldcnt & target2) return blend5(c, below.color, top.alpha5);
        // Otherwise the 3D layer acts as BG0 (first-target bit 0x01) for
        // brightness effects only; alpha blend never applies here.
        if (effects_enabled && (u.bldcnt & top.target)) {
            switch ((u.bldcnt >> 6) & 3u) {
                case 2: return brighten(c, u.evy);
                case 3: return darken(c, u.evy);
            }
        }
        return c;
    }
    if(top.alpha && (u.bldcnt&target2)){
        const uint32_t eva=top.alpha==0xFFu?u.eva:top.alpha;
        c=blend(c,below.color,eva,top.alpha==0xFFu?u.evb:16u-eva);
    }else if(effects_enabled && (u.bldcnt&top.target)){
        switch((u.bldcnt>>6)&3u){
            case 1:if(u.bldcnt&target2)c=blend(c,below.color,u.eva,u.evb);break;
            case 2:c=brighten(c,u.evy);break;
            case 3:c=darken(c,u.evy);break;
        }
    }
    return c;
}

// ---- Per-line latch and per-render scratch --------------------------------
// A line render is a pure function of a latched register snapshot plus the
// memory views; it never reads g_unit and never mutates guest state. The
// scheduler thread owns the latch (and therefore the affine accumulators and
// the DISPCAPCNT enable latch). See docs/device_work_parallelization.md.
struct LineScratch {
    std::array<BgLine, 4> bg_lines{};
    std::array<uint32_t, 256> comp6{};
    std::array<Pixel, 256> obj{};
    std::array<uint8_t, 256> obj_window{};
    // Profiling accumulators, merged into the module counters at a drain so
    // concurrent renders cannot tear them.
    uint64_t obj_ns = 0;
    uint64_t engine_ns[2] = {};
    uint64_t text_lines[2][5] = {};
    uint64_t no_effect_lines[2] = {};
    uint64_t scanlines = 0;
    uint64_t render_ns = 0;
    uint64_t direct_class_engine_a_ns[NDS_GPU2D_DIRECT_CLASS_COUNT] = {};
    uint64_t direct_extra_bg_mask_engine_a_ns[
        NDS_GPU2D_DIRECT_BG_MASK_COUNT] = {};
};

struct LineJob {
    Unit unit[2]{};
    const uint8_t* palette[2]{};
    const uint8_t* oam[2]{};
    const NdsVramRendererView* vram[2]{};
    // Owned copy: GPU3D::GetLine returns a pointer into shared scratch that is
    // valid only until the next call, and SoftRenderer::GetLine consumes
    // scanline-semaphore tokens, so only the scheduler thread may call it.
    std::array<uint32_t, 256> line3d_storage{};
    const uint32_t* line3d = nullptr;
    uint32_t buffer = 0;
    uint32_t screen[2]{};
    int y = 0;
    bool engine_active[2]{};
    bool bg0_3d = false;
    bool cap = false;
    uint32_t capw = 0;
    uint8_t direct_class = 0;
    uint8_t direct_extra_bg_mask = 0;
    uint32_t* direct_pixels = nullptr;
    uint32_t* direct_params = nullptr;
    uint16_t direct_width = 0;
    bool direct_powered = true;
    // Staged display capture. The pixels are produced by whichever thread
    // renders the line; the write into guest VRAM, and the texture-generation
    // bump that goes with it, are applied by the scheduler thread in line
    // order at the next drain. capture_count == 0 means nothing was staged
    // (no capture on this line, or the destination bank is not LCDC-mapped,
    // in which case the hardware writes nothing either).
    std::array<uint16_t, 256> capture_pixels{};
    uint32_t capture_dstaddr = 0;
    uint32_t capture_dstbank = 0;
    uint32_t capture_count = 0;
};

// The set of BG layers this engine decodes on this line. Single source of
// truth for the decoders and for the affine-accumulator advance (F4).
uint8_t bg_active_mask(const Unit& u, bool bg0_3d) {
    uint8_t mask = 0;
    for (int bg = 0; bg < 4; ++bg) {
        if (!(u.dispcnt & (0x100u << bg))) continue;
        if (bg == 0 && bg0_3d) continue;   // BG0's slot is the 3D layer
        if (bg_kind(u, bg) != BgKind::None) mask |= static_cast<uint8_t>(1u << bg);
    }
    return mask;
}

// Composite one scanline into the internal 6-bit format (channels at bits
// 0-5/8-13/16-21) including the 3D layer when BG0 is redirected to it.
// This is the general-path twin of the dst-direct fast paths in
// render_engine_line, which carry the same layer/priority/blend rules but
// skip the 3D layer and the 6-bit intermediate.
void compose_line6(int engine, int y, const Unit& u, const uint8_t* palette,
                   const uint8_t* oam, const NdsVramRendererView& vram,
                   const uint32_t* line3d, bool bg0_3d, uint32_t* out,
        if (line_general_path(snapshot, e, bg0_3d_e, cap_e)) {
            const uint32_t mode = (snapshot.dispcnt >> 16) & (e ? 1u : 3u);
            const bool need_comp =
                mode == 1u || (cap_e && !(snapshot.capture & 0x01000000u));
            if (!need_comp) continue;   // nothing decoded, nothing advances
        }
        const uint8_t active = bg_active_mask(snapshot, bg0_3d_e);
        for (int bg = 2; bg < 4; ++bg)
            if (active & (1u << bg)) advance_affine_line(g_unit[e], bg);
    }
}

void render_direct_window_line(const LineJob& job) {
    const Unit& u = job.unit[0];
    const bool views = job.palette[0] && job.oam[0] && job.vram[0];
    const bool supported = views && job.direct_powered && job.screen[0] == 0u && !job.cap &&
        ((u.dispcnt >> 16) & 3u) == 1u &&
        (u.dispcnt & 0x108u) == 0x108u && !(u.dispcnt & 0xE00u);
    if (!supported)
        g_window_direct_unsupported_lines.fetch_add(1, std::memory_order_relaxed);
    if (!views) {
        std::fill_n(job.direct_pixels, job.direct_width, 0x4040u);
        std::fill_n(job.direct_params, 4, 0u);
        return;
    }
    std::array<Pixel, kMaxAdaptiveWidth> obj{};
    std::array<uint8_t, kMaxAdaptiveWidth> obj_window{};
    render_obj_line(u, 0, job.y, obj.data(), job.direct_width,
        job.oam[0], job.palette[0], *job.vram[0], obj_window.data());
    const NdsGpu2dWindowState windows{u.dispcnt, u.win};
    const int extra = (job.direct_width - 256) / 2;
    const bool blank = (u.dispcnt & 0x80u) != 0u;
    for (int x = 0; x < job.direct_width; ++x) {
        const int hud_x = nds_gpu2d_adaptive_hud_x(x, job.direct_width,
            g_adaptive_hud_anchor, g_adaptive_hud_center_width);
        const uint8_t mask = nds_gpu2d_window_mask(windows,
            nds_gpu2d_adaptive_window_x(x, extra, hud_x),
            static_cast<uint8_t>(job.y), obj_window[x] != 0u);
        const auto& p = obj[x];
        job.direct_pixels[x] = blank
            ? nds_gpu2d_pack_direct_pixel(0x003F3F3Fu, 0, 0, true, 0x10u)
            : nds_gpu2d_pack_direct_pixel(p.color, p.priority, p.alpha, p.valid, mask);
    }
    job.direct_params[0] = rgb6(view16(job.palette[0], 0));
    job.direct_params[1] = blank ? 0u :
        uint32_t(u.bldcnt) | (uint32_t(u.master_bright) << 16);
    job.direct_params[2] = uint32_t(u.eva) | (uint32_t(u.evb) << 8) |
        (uint32_t(u.evy) << 16) | (uint32_t(u.bgcnt[0] …559 tokens truncated…f (g_adaptive_center_max_polygons != 0u &&
        nds_gpu3d_render_polygon_count() <= g_adaptive_center_max_polygons &&
        !nds_gpu3d_projection_has_perspective())
        return center_native(NDS_GPU2D_ADAPTIVE_LOW_POLYGON);

    Unit& u = g_unit[0];
    const uint8_t* const palette = nds_vram_renderer_palette(0);
    const uint8_t* const oam = nds_vram_renderer_oam(0);
    const NdsVramRendererView* const vram = nds_vram_renderer_view(0);
    const uint32_t mode = (u.dispcnt >> 16) & 3u;
    const bool bg0_3d = (u.dispcnt & 0x8u) != 0 &&
                        (u.dispcnt & 0x100u) != 0;
    // PMD Sky's dungeon compositor is text-BG based. Widen those layers by
    // sampling the same 512x256 maps outside the vanilla viewport before the
    // 3D-only adaptive path rejects the scene.
    if (!bg0_3d && palette && oam && vram && wide_2d_scene_supported(u)) {
        if (composite_2d_wide_frame(u, palette, oam, *vram, output_width,
                                    extra, adaptive)) {
            ++g_adaptive_fallback_frames[NDS_GPU2D_ADAPTIVE_WIDE];
            return adaptive.data();
        }
    }
    // Known-safe adaptive scenes use main-engine 3D plus OBJ. Text BG planes
    // can either be title-anchored into left/center/right bands or kept as a
    // native-width centered overlay. Affine/bitmap backgrounds still retain a
    // centered native image; windowed text scenes use the same native stack
    // filtering as the regular compositor below.
    bool supported_hud_bgs = true;
    for (int bg = 1; bg < 4; ++bg) {
        if ((u.dispcnt & (0x100u << bg)) &&
            bg_kind(u, bg) != BgKind::Text) {
            supported_hud_bgs = false;
            break;
        }
    }
    const NdsGpu2dWindowState window_state{u.dispcnt, u.win};
    // DS windows do not disqualify a scene from wide composition: the
    // compositor applies the full per-pixel window mask (rectangular windows
    // through the native edge-column mapping, the OBJ window from its own
    // wide-rasterized coverage). Titles such as Mario Kart DS race with
    // Win0/Win1/OBJ-window enabled on every frame, and treating that as
    constexpr int kLowestObjectX = -128;
    const int margin = metrics_.left_margin;
    const int min_x = std::max(kPieceReachLeft - margin, kLowestObjectX);
    const int max_x = gpu2d::kVanillaWidth + metrics_.right_margin;
    return vanilla_piece_x < min_x || vanilla_piece_x >= max_x;
}

/// Samples a single 8x8 tilemap entry from an `overlay11` 3x3 chunk `map_render` structure.
uint16_t DungeonCameraHook::SampleGroundMapTileEntry(
    GuestMemoryView mem,
    uint32_t map_render_addr,
    int bg_index,
    int tile_col,
    int tile_row) noexcept {
    if (!mem.in_range(map_render_addr, layout::ground::kMapRenderSize) || bg_index < 0 || bg_index >= 2) {
        return 0u;
    }

    // Ported from Asphaltian/pmd-space MapRender.Entry (GroundBg.cs, GPL-3.0).
    const int16_t chunk_dims =
        mem.read_or<int16_t>(map_render_addr + layout::ground::kMapRenderChunkDimensionsOffset, 0);
    if (chunk_dims != layout::ground::kMapRenderChunks3x3) {
        return 0u;
    }

    auto div_floor_chunk = [](int tiles, int& out_chunk, int& out_tile) noexcept {
        constexpr int kChunk = layout::ground::kChunkTileSize;
        int q = tiles / kChunk;
        int r = tiles % kChunk;
        if (r < 0) {
            --q;
            r += kChunk;
        }
        out_chunk = q;
        out_tile = r;
    };

    int chunk_col = 0;
    int sub_col = 0;
    int chunk_row = 0;
    int sub_row = 0;
    div_floor_chunk(tile_col, chunk_col, sub_col);
    div_floor_chunk(tile_row, chunk_row, sub_row);

    const uint8_t wrap_around =
        mem.read_or<uint8_t>(map_render_addr + layout::ground::kMapRenderWrapAroundOffset, 0u);
    const int width_chunks =
        mem.read_or<int32_t>(map_render_addr + layout::ground::kMapRenderWidthChunksOffset, 0);
    const int height_chunks =
        mem.read_or<int32_t>(map_render_addr + layout::ground::kMapRenderHeightChunksOffset, 0);
    if (width_chunks <= 0 || width_chunks > layout::ground::kChunkMapStride ||
        height_chunks <= 0 || height_chunks > layout::ground::kChunkMapStride) {
        return 0u;
    }

    if (wrap_around != 0u) {
        chunk_col = ((chunk_col % width_chunks) + width_chunks) % width_chunks;
        chunk_row = ((chunk_row % height_chunks) + height_chunks) % height_chunks;
    } else if (chunk_col < 0 || chunk_col >= width_chunks || chunk_row < 0 || chunk_row >= height_chunks) {
        return 0u;
    }

    const uint32_t chunks_ptr = mem.read_or<uint32_t>(
        map_render_addr + layout::ground::kMapRenderChunkMapPtrOffset + static_cast<uint32_t>(bg_index * 4),
        0u);
    const uint32_t chunk_tiles_ptr = mem.read_or<uint32_t>(
        map_render_addr + layout::ground::kMapRenderChunkTilesPtrOffset + static_cast<uint32_t>(bg_index * 4),
        0u);
    if (!mem.in_range(chunks_ptr, sizeof(uint16_t)) ||
        !mem.in_range(chunk_tiles_ptr, sizeof(uint16_t))) {
        return 0u;
    }

    const uint32_t chunk_idx_addr =
        chunks_ptr + static_cast<uint32_t>((chunk_row * layout::ground::kChunkMapStride + chunk_col) * 2);
    const auto chunk_id = mem.read<uint16_t>(chunk_idx_addr);
    if (!chunk_id.has_value()) {
        return 0u;
    }

    constexpr int kChunkArea = layout::ground::kChunkTileSize * layout::ground::kChunkTileSize;
    const uint32_t tile_entry_addr =
        chunk_tiles_ptr +
        static_cast<uint32_t>((static_cast<int>(*chunk_id) * kChunkArea +
                               sub_row * layout::ground::kChunkTileSize + sub_col) * 2);
    return mem.read_or<uint16_t>(tile_entry_addr, 0u);
}

/// Detects whether a Ground Mode `ground_bg` represents a static 256x192 full-screen illustration.
bool DungeonCameraHook::IsGroundMapStaticFullScreenPicture(
    GuestMemoryView mem,
    uint32_t ground_bg_addr) const noexcept {
    if (!mem.in_range(ground_bg_addr, layout::ground::kGroundBgSize)) {
        return false;
    }

    // Dialogue scenes can have active performers over a static full-screen
    // backdrop. Decide from the background map bounds, not actor presence.
    const int cam_count =
        mem.read_or<int32_t>(ground_bg_addr + layout::ground::kGroundBgCameraCountOffset, 0);
    if (cam_count < 1 || cam_count > 2) {
        return false;
    }

    constexpr int kVanillaColumns = gpu2d::kVanillaWidth / 8; // 32
    constexpr int kVanillaRows = gpu2d::kVanillaHeight / 8;   // 24

    for (int idx = 0; idx < cam_count; ++idx) {
        const uint32_t mr_addr =
            ground_bg_addr + layout::ground::kGroundBgMapRenderOffset +
            static_cast<uint32_t>(idx) * layout::ground::kMapRenderSize;
        const int16_t chunk_dims =
            mem.read_or<int16_t>(mr_addr + layout::ground::kMapRenderChunkDimensionsOffset, 0);
        if (chunk_dims != layout::ground::kMapRenderChunks3x3) {
            return false;
        }

        const int num_bgs =
            mem.read_or<int16_t>(mr_addr + layout::ground::kMapRenderNumBgsOffset, 0);
        const int width_chunks =
            mem.read_or<int32_t>(mr_addr + layout::ground::kMapRenderWidthChunksOffset, 0);
        const int height_chunks =
            mem.read_or<int32_t>(mr_addr + layout::ground::kMapRenderHeightChunksOffset, 0);
        constexpr int kMaxChunks = layout::ground::kChunkMapStride;
        if (num_bgs < 1 || num_bgs > 2 || width_chunks < 1 || width_chunks > kMaxChunks ||
            height_chunks < 1 || height_chunks > kMaxChunks) {
            return false;
        }
        const int total_cols = width_chunks * layout::ground::kChunkTileSize;
        const int total_rows = height_chunks * layout::ground::kChunkTileSize;

        int first_col = total_cols;
        int last_col = -1;
        int first_row = total_rows;
        int last_row = -1;

        for (int bg = 0; bg < num_bgs; ++bg) {
            for (int r = 0; r < total_rows; ++r) {
                for (int c = 0; c < total_cols; ++c) {
                    if (SampleGroundMapTileEntry(mem, mr_addr, bg, c, r) != 0u) {
                        first_col = std::min(first_col, c);
                        last_col = std::max(last_col, c);
                        first_row = std::min(first_row, r);
                        last_row = std::max(last_row, r);
                        if (last_col - first_col >= kVanillaColumns ||
                            last_row - first_row >= kVanillaRows) {
                            return false;
                        }
                    }
                }
            }
        }

        if (last_col < first_col || last_row < first_row) {
            return false;
        }
    }

    return true;
}

