bool resize_top_screen_texture(
    FrontendPresentation& presentation, int width,
    skyrecomp::shaders::ShaderFilterPreset filter) {
    if (width <= 0 || presentation.renderers[0] == nullptr) return false;
    SDL_Texture* new_texture = SDL_CreateTexture(
        presentation.renderers[0], SDL_PIXELFORMAT_ARGB8888,
        SDL_TEXTUREACCESS_STREAMING, width, kScreenHeight);
    if (new_texture == nullptr) return false;
    SDL_Texture* new_sample = nullptr;
    if (presentation.sample_scale > 1) {
        new_sample = SDL_CreateTexture(
            presentation.renderers[0], SDL_PIXELFORMAT_ARGB8888,
            SDL_TEXTUREACCESS_TARGET, width * presentation.sample_scale,
            kScreenHeight * presentation.sample_scale);
        if (new_sample == nullptr) {
            SDL_DestroyTexture(new_texture);
            return false;
        }
    }
    if (presentation.textures[0] != nullptr) {
        SDL_DestroyTexture(presentation.textures[0]);
    }
    if (presentation.sample_targets[0] != nullptr) {
        SDL_DestroyTexture(presentation.sample_targets[0]);
    }
    presentation.textures[0] = new_texture;
    presentation.sample_targets[0] = new_sample;
    presentation.screen_widths[0] = width;
    apply_sky_shader_filter(presentation, filter);
    return true;
}

void apply_single_screen_presentation(FrontendPresentation& presentation,
                                      bool single_screen) {
    if (presentation.separate) {
        if (!presentation.windows[1]) return;
        if (single_screen)
            SDL_HideWindow(presentation.windows[1]);
        else
            SDL_ShowWindow(presentation.windows[1]);
        return;
    }
    if (!presentation.windows[0] || !presentation.renderers[0]) return;
    const auto window_flags = SDL_GetWindowFlags(presentation.windows[0]);
    const bool fullscreen = (window_flags & SDL_WINDOW_FULLSCREEN) != 0;
    int window_w = 0;
    int window_h = 0;
    SDL_GetWindowSize(presentation.windows[0], &window_w, &window_h);
    const int canvas_w = presentation.canvas_width;
    const int stacked_h = kScreenHeight * 2;
    const int logical_h = single_screen ? kScreenHeight : stacked_h;
    if (!fullscreen && window_w > 0 && window_h > 0) {
        const int scale = std::max(1, window_w / std::max(1, canvas_w));
        SDL_SetWindowSize(presentation.windows[0], canvas_w * scale,
                          logical_h * scale);
    }
    set_render_logical_size(presentation.renderers[0], canvas_w, logical_h);
}

