    // beads-yjp.28: recording is unconditional. This used to be gated behind
    // g_discover_static_misses, which no shipped launcher passes, so a
    // player's process kept an empty map for its entire run and their
    // playthrough taught the project nothing. The map deduplicates on
    // (cpu, pc, mode, kind) and only counts hits after the first, so the
    // steady-state cost is one hash lookup on a path that has already run a
    // full interpreter step. The flag keeps its OTHER meaning below -- the
    // static-BIOS-miss execution allowance -- which stays opt-in.
    pc &= ~1u;
    const uint8_t cpu = g_nds_active == NDS_ARM7 ? 1u : 0u;
    const uint64_t key = uint64_t{pc} |
                         (uint64_t{kind} << 32u) |
                         (uint64_t{thumb ? 1u : 0u} << 40u) |
                         (uint64_t{cpu} << 41u);
    auto found = g_coverage_index.find(key);
    if (found != g_coverage_index.end()) {
        ++g_coverage[found->second].hits;
        return;
    }
    g_coverage_index.emplace(key, static_cast<uint32_t>(g_coverage.size()));
    g_coverage.push_back({1u, pc, caller, cpu,
                          static_cast<uint8_t>(thumb ? 1u : 0u), kind});
}

template<class State>
uint32_t pack_cpsr(const State& c) {
    return (uint32_t(c.cpsr.n) << 31) | (uint32_t(c.cpsr.z) << 30) |
           (uint32_t(c.cpsr.c) << 29) | (uint32_t(c.cpsr.v) << 28) |
           (uint32_t(c.cpsr.q) << 27) |
           (uint32_t(c.cpsr.i) << 7)  | (uint32_t(c.cpsr.f) << 6)  |
           (uint32_t(c.cpsr.t) << 5)  | uint32_t(c.cpsr.mode);
}

bool trace_pc(uint32_t pc) {
    return (pc >= 0x021F0000u && pc < 0x021F0040u) ||
           (pc >= 0x0231FE00u && pc < 0x0231FE80u) ||
           (pc >= 0x037FD7A0u && pc < 0x037FD7C0u) ||
           (pc >= 0x0380F800u && pc < 0x0380F900u);
}

bool static_bios_pc(uint32_t pc) {
    return (g_nds_active == NDS_ARM9)
        ? (pc >= 0xFFFF0000u && pc < 0xFFFF1000u)
        : (pc < 0x00004000u);
}

template<class State>
void trace_push(const State& c, uint8_t phase, uint32_t pc,
                uint32_t raw, uint32_t next_pc, uint8_t result) {
    Tier3TraceEvent& e = g_trace[g_trace_w];
    e.seq = ++g_trace_seq;
    e.cpu = static_cast<uint8_t>(g_nds_active);
    e.thumb = c.cpsr.t ? 1 : 0;


def run_recompiler_for_bank(
    recompiler: Path,
    bank: BankSpec,
    gen_dir: Path,
    audit_only: bool,
    max_function_bytes: int,
) -> Tuple[str, int, str]:
    """Audit or compile one bank and collect the subprocess result."""
    cmd = [
        str(recompiler),
        "--config",
        str(bank.toml_path),
        "--bin",
        str(bank.bin_path),
        "--bank",
        bank.bank_name,
    ]
    if audit_only:
        cmd.append("--audit")
    else:
        cmd.extend([
            "--out",
            str(gen_dir),
            "--validate-live-bytes",
            "--coalesce-fallthroughs",
            "--max-function-bytes",
            str(max_function_bytes),
            "--shards",
            str(bank.shards),
            "--stable-address-shards",
        ])
    proc = subprocess.run(cmd, capture_output=True, text=True)
    out = (proc.stdout or "") + (proc.stderr or "")
    return bank.bank_name, proc.returncode, out


def resolve_output_dirs(
    repo_root: Path,
    rom_sha1: str,
    region: str,
    out_dir: Path,
    gen_dir: Path,
    is_default_out: bool,
    is_default_gen: bool,
) -> Tuple[Path, Path]:
    """Resolve extraction and generated-bank cache directories, isolating custom ROMs."""
    reg_code = "us" if region in ("NA", "US") else region.lower()
    if rom_sha1 in KNOWN_ROMS:
        resolved_out = (repo_root / "build" / f"extracted_sky_{reg_code}") if is_default_out else out_dir

