constexpr uint32_t kSpecialTileIndexOffset = 0x40D8;
constexpr uint32_t kDungeonIdOffset = 0x40DA;
constexpr int kSubtilesPerAxis = 3;
constexpr int kEntriesPerMetatile = kSubtilesPerAxis * kSubtilesPerAxis;

