PresentationTicks present_screens(FrontendPresentation& presentation,
                                  const uint32_t* top_pixels,
                                  int top_width,
                                  const uint32_t* bottom_pixels,
                                  int bottom_width,
                                  RecompRuntimeUi* runtime_ui,
