void render_texture(SDL_Renderer* renderer, SDL_Texture* texture,
                    const SDL_Rect* destination, const SDL_Rect* source = nullptr) {
#if defined(NDS_HAVE_SDL3)
    SDL_FRect src{};
    if (source)
        src = {float(source->x), float(source->y), float(source->w), float(source->h)};
    SDL_FRect dst{};
    const SDL_FRect* dst_ptr = nullptr;
    if (destination) {
        dst.x = static_cast<float>(destination->x);
        dst.y = static_cast<float>(destination->y);
        dst.w = static_cast<float>(destination->w);
        dst.h = static_cast<float>(destination->h);
        dst_ptr = &dst;
    }
    SDL_RenderTexture(renderer, texture, source ? &src : nullptr, dst_ptr);
#else
    SDL_RenderCopy(renderer, texture, source, destination);
#endif
}

