void draw_post_filter(SDL_Renderer* renderer, const SDL_Rect& destination,
                      SkyPostFilter filter) {
    if (filter == SkyPostFilter::None || destination.w <= 0 ||
        destination.h <= 0) {
        return;
    }
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
    if (filter == SkyPostFilter::CrtScanline) {
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 72);
        for (int y = destination.y; y < destination.y + destination.h; y += 2) {
            render_line(renderer, destination.x, y,
                        destination.x + destination.w - 1, y);
        }
    } else if (filter == SkyPostFilter::LcdGrid) {
        const int step_x = std::max(1, destination.w / kScreenWidth);
        const int step_y = std::max(1, destination.h / kScreenHeight);
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 28);
        for (int x = destination.x; x < destination.x + destination.w;
             x += step_x) {
            render_line(renderer, x, destination.y,
                        x, destination.y + destination.h - 1);
        }
        for (int y = destination.y; y < destination.y + destination.h;
             y += step_y) {
            render_line(renderer, destination.x, y,
                        destination.x + destination.w - 1, y);
        }
    }
}

void render_screen(FrontendPresentation& presentation, int screen,
                   const SDL_Rect& destination) {
    SDL_Renderer* renderer = presentation.renderers[screen];
    SDL_Texture* source = presentation.textures[screen];
    SDL_Rect source_rect{0, 0, presentation.screen_widths[screen], kScreenHeight};
    if (presentation.sample_scale > 1 && presentation.sample_targets[screen]) {
        const SDL_Rect sample_rect{
            0, 0, source_rect.w * presentation.sample_scale,
            source_rect.h * presentation.sample_scale};
        SDL_SetRenderTarget(renderer, presentation.sample_targets[screen]);
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);
        render_texture(renderer, source,
                       presentation.sky_adaptive ? &sample_rect : nullptr,
                       presentation.sky_adaptive ? &source_rect : nullptr);
        SDL_SetRenderTarget(renderer, nullptr);
        source = presentation.sample_targets[screen];
        source_rect = sample_rect;
    }
    render_texture(renderer, source, &destination,
                   presentation.sky_adaptive ? &source_rect : nullptr);
    draw_post_filter(renderer, destination, presentation.post_filter);
}

void apply_sky_shader_filter(FrontendPresentation& presentation,
                             skyrecomp::shaders::ShaderFilterPreset filter) {
    bool linear = true;
    presentation.post_filter = SkyPostFilter::None;
    switch (filter) {
        case skyrecomp::shaders::ShaderFilterPreset::Nearest:
        case skyrecomp::shaders::ShaderFilterPreset::Pixellate:
            linear = false;
            break;
        case skyrecomp::shaders::ShaderFilterPreset::NdsLcdSubpixelGrid:
            presentation.post_filter = SkyPostFilter::LcdGrid;
            break;
        case skyrecomp::shaders::ShaderFilterPreset::CrtScanline:
            presentation.post_filter = SkyPostFilter::CrtScanline;
            break;
        case skyrecomp::shaders::ShaderFilterPreset::SharpBilinear:
        default:
            break;
    }
    for (int screen = 0; screen < 2; ++screen) {
        if (presentation.textures[screen]) {
            (linear ? set_texture_scale_linear : set_texture_scale_nearest)(
                presentation.textures[screen]);
        }
        if (presentation.sample_targets[screen]) {
            (linear ? set_texture_scale_linear : set_texture_scale_nearest)(
                presentation.sample_targets[screen]);
        }
    }
}

