    const bool has_ground_bg = mem.in_range(ground_bg_ptr, layout::ground::kGroundBgSize);
    const bool has_ground_ptrs = mem.in_range(syms.GROUND_STATE_PTRS, layout::ground::kMainGroundDataSize);

