    const bool engine_a_on_top = (nds_powercontrol9() & 0x8000u) != 0;
    const int engine = engine_a_on_top ? screen : (screen ^ 1);
    // Cleared so every early return below (native width, unsupported scene)
    // leaves the presenter on the CPU composite rather than re-reading last
    // frame's surfaces. Guarded on engine A: this function is called once per
    // screen, and an unguarded reset here would let the engine-B call wipe
    // the flag the engine-A call just set, silently disabling HD entirely.
    if (engine == 0) g_hd_frame_valid = false;
    const int output_width = nds_gpu3d_output_width();
    if (output_width < 256 || (output_width == 256 && !g_hd_emit_enabled)) {
        if (width) *width = 256;
        return native;
    }
    static bool logged_adaptive_top = false;
    if (!logged_adaptive_top && screen == 0 && output_width > 256) {
        logged_adaptive_top = true;
        const Unit& tu = g_unit[engine];
        std::fprintf(stderr,
                     "[gpu2d] adaptive top: engine=%d mode=%u "
                     "dispcnt=%08x bg0=%04x bg1=%04x bg2=%04x bg3=%04x "
                     "capture=%d xpos=%d center_native=%d lowpoly=%u\n",
                     engine, (tu.dispcnt >> 16) & 3u, tu.dispcnt,
                     tu.bgcnt[0], tu.bgcnt[1], tu.bgcnt[2], tu.bgcnt[3],
                     g_present_capture_active ? 1 : 0,
                     static_cast<int>(nds_gpu3d_render_xpos()),
                     g_adaptive_center_native ? 1 : 0,
                     g_adaptive_center_max_polygons);
    }

    AdaptiveFrame& adaptive = g_adaptive_frame[screen & 1];
    if (width) *width = static_cast<uint16_t>(output_width);
    // At native width every fallback copies or returns the complete native
    // framebuffer, while HD needs only the separate survivor-layer surfaces.
    if (output_width != 256)
        std::fill_n(adaptive.data(),
                    static_cast<size_t>(output_width) * 192u,
                    0xFF000000u);
    const int extra = (output_width - 256) / 2;
    // Native-width composite centred in the adaptive window. Every reason is
    // counted so a pillarboxed title can be diagnosed from the live counters
    // (frontend_stats / profile) instead of by guessing.
    auto center_native = [&](NdsGpu2dAdaptiveFallback reason) {
        ++g_adaptive_fallback_frames[reason];
        for (int y = 0; y < 192; ++y)
            std::copy_n(native + y * 256, 256,
                        adaptive.data() + y * output_width + extra);
        return adaptive.data();
    };
    if (g_wide_affine_enabled && engine == 0 && output_width > 256) {
        const auto& lines = g_wide_affine_lines[g_front];
        const bool has_affine = std::any_of(lines.begin(), lines.end(),
            [](const WideAffineLine& line) { return line.has_affine; });
        if (has_affine) {
            if (g_adaptive_center_native || scene == NdsGpu2dScene::StaticPicture)
                return center_native(NDS_GPU2D_ADAPTIVE_CENTER_NATIVE);
            const bool complete = std::all_of(lines.begin(), lines.end(),
                [output_width, screen](const WideAffineLine& line) {
                    return line.width == output_width && line.screen == screen;
                });
            if (scene == NdsGpu2dScene::ScrollingGroundMap && complete) {
                for (int y = 0; y < 192; ++y) {
                    uint32_t* const dst = adaptive.data() + y * output_width;
                    const uint32_t* const wide =
                        g_wide_affine_frame[g_front].data() + y * kMaxAdaptiveWidth;
                    std::copy_n(wide, extra, dst);
                    std::copy_n(native + y * 256, 256, dst + extra);
                    std::copy_n(wide + extra + 256, extra, dst + extra + 256);
