        if (!dungeon_map || !dungeon_map->entries ||
            !(u.dispcnt & 0x800u) || (u.bgcnt[3] >> 14) != 1u ||
            u.bgx[3] != (dungeon_map->scroll_x & 0x1FF) ||
            (u.bgy[3] & 0xFF) != (dungeon_map->scroll_y & 0xFF)) {
