    const auto sf_warp = interp.EvaluateSubFrame(0.50f);
    assert(sf_warp.dungeon_poses[0].snapped_discontinuity);
    assert(sf_warp.dungeon_poses[0].interp_x_q8 == 244 * 256);
    assert(sf_warp.dungeon_poses[0].subpixel_dx_q8 == 0);

