    /// Returns a const pointer to `[guest_addr, guest_addr + byte_count)` in Main RAM, or `nullptr` if out of bounds.
    [[nodiscard]] const uint8_t* raw_ptr(uint32_t guest_addr, size_t byte_count) const noexcept {
