// the physical bank backing that 16 KiB virtual window. Legal overlapping
// bank mappings stay null and use the exact OR-combining fallback.
struct NdsVramRendererView {
    const uint8_t* bg[32];
    const uint8_t* obj[16];
};
const NdsVramRendererView* nds_vram_renderer_view(int engine);

// 3D renderer flattened texture views: refresh the OR-combined texture-slot
// space (4 x 128 KiB) / texture-palette-slot space (8 x 16 KiB) into the
// caller's buffer. Unmapped slots read as zero.
void nds_vram_copy_texture(uint8_t* dst);   // 512 KiB
void nds_vram_copy_texpal(uint8_t* dst);    // 128 KiB

// Display-capture unit access (engine A DISPCAPCNT). Capture reads/writes
// the physical bank storage directly, gated only on the bank being mapped
// to LCDC (melonDS DoCapture); it does not go through the CPU mapping.
bool nds_vram_lcdc_mapped(unsigned bank);
};

TextLine prepare_text_line(const Unit& u, int engine, int bg, int y,
                           const uint8_t* palette,
                           const NdsVramRendererView* vram) {
    TextLine line{};
    line.u = &u;
    line.engine = engine;
    line.bg = bg;
    line.palette = palette;
    line.vram = vram;
    line.cnt = u.bgcnt[bg];
    const uint32_t size = line.cnt >> 14;
    line.sy = (u.bgy[bg] + y) & 0x1FFu;
    if (!(size & 2u)) line.sy &= 0xFFu;
    if ((line.cnt & 0x40u) && u.bg_mosaic_y)
        line.sy -= y % (u.bg_mosaic_y + 1u);
    line.char_base = (line.cnt & 0x003Cu) << 12;
    line.map_base = (line.cnt & 0x1F00u) << 3;
    if (!engine) {
        line.char_base += (u.dispcnt & 0x07000000u) >> 8;
        line.map_base += (u.dispcnt & 0x38000000u) >> 11;
    }
    line.width_extra = (line.cnt & 0x4000u) ? 0x100u : 0u;
    return line;
}

Pixel text_pixel(TextLine& line, int x, const uint16_t* dungeon_tiles = nullptr) {
    const Unit& u = *line.u;
    const uint16_t cnt = line.cnt;
    const int bg = line.bg;
    uint32_t sx = (u.bgx[bg] + x) & 0x1FFu;
    const uint32_t size = cnt >> 14;
    if (!(size & 1u)) sx &= 0xFFu;
    if ((cnt & 0x40u) && u.bg_mosaic_x) sx -= x % (u.bg_mosaic_x + 1u);
    uint32_t map_addr = line.map_base;
    if (cnt & 0x8000u) {
        map_addr += (line.sy & 0x1F8u) << 3;
        if (cnt & 0x4000u) map_addr += (line.sy & 0x100u) << 3;
    } else map_addr += (line.sy & 0xF8u) << 3;
    map_addr += ((sx & 0xF8u) >> 2) + ((sx & line.width_extra) << 3);
    if (map_addr != line.cached_map_addr || dungeon_tiles != line.cached_map_source) {
        line.cached_map_addr = map_addr;
        line.cached_map_source = dungeon_tiles;
        line.cached_tile = dungeon_tiles
            ? dungeon_tiles[(line.sy >> 3u) * 64u + (sx >> 3u)]
            : static_cast<uint16_t>(bg_view16(*line.vram, line.engine, map_addr));
    }
    const uint16_t tile = line.cached_tile;
    uint32_t tx = sx & 7u, ty = line.sy & 7u;
    if (tile & 0x0400u) tx = 7u-tx;
    if (tile & 0x0800u) ty = 7u-ty;
    uint8_t index;
    uint16_t color;
    if (cnt & 0x0080u) {
        index = bg_view8(*line.vram, line.engine,
            line.char_base+((tile&0x3FFu)<<6)+(ty<<3)+tx);
        if (!index) return {};
        if (u.dispcnt & 0x40000000u) {
            const uint32_t slot = (bg<2 && (cnt&0x2000u)) ? 2u+bg : static_cast<uint32_t>(bg);
            color = static_cast<uint16_t>(nds_vram_read_bg_extpal(line.engine,(slot<<13)+((tile>>12)<<9)+(index<<1),2));
        } else color = view16(line.palette,index<<1);
    } else {
        const uint8_t packed = bg_view8(*line.vram, line.engine,
            line.char_base+((tile&0x3FFu)<<5)+(ty<<2)+(tx>>1));
        index = (tx&1u) ? packed>>4 : packed&0xFu;
        if (!index) return {};
        color = view16(line.palette,(((tile>>12)&0xFu)<<5)+(index<<1));
    }
    // NOTE: color is returned in raw 15-bit form; the per-tile line decoder
    // below is the primary path and its buffers hold 15-bit colors. This
    // per-pixel routine remains as the exact-semantics fallback for mosaic.
    return {color, static_cast<uint8_t>(1u << bg), 0,
            static_cast<uint8_t>(cnt & 3u), static_cast<uint8_t>(bg + 1), true};
}

// One decoded text-BG scanline. Per-pixel storage is the raw 15-bit color
// with bit 15 as the "opaque" flag; target/priority/order are per-layer
    }

    // The 3D line and the wide-3D snapshot are pulled here, in scanline order,
    // under exactly the condition the inline render used: GPU3D::GetLine writes
    // a single shared scratch buffer and SoftRenderer::GetLine consumes
    // scanline-semaphore tokens, so no other thread may call it.
    const bool engine_a_renders =
        job.engine_active[0] && !line_forceblank(job, 0);
    if (g_capture_dungeon_raster && engine_a_renders && !job.cap &&
        job.palette[0] && job.oam[0]) {
        auto& raster = g_dungeon_raster[job.buffer];
        const auto& u = job.unit[0];
        if (y == 0) {
            raster.unit = u;
            raster.screen = job.screen[0];
            std::copy_n(job.palette[0], raster.palette.size(), raster.palette.data());
            std::copy_n(job.oam[0], raster.oam.size(), raster.oam.data());
        }
        if (raster.lines == y && raster.screen == job.screen[0] &&
            raster.unit.bgx[3] == u.bgx[3] && raster.unit.bgy[3] == u.bgy[3])
            ++raster.lines;
    }
    if (engine_a_renders &&
        line_general_path(job.unit[0], 0, job.bg0_3d, job.cap)) {
        const bool capture_uses_3d = job.cap &&
            ((job.unit[0].capture >> 29) & 3u) != 1u &&
            ((job.unit[0].capture & (1u << 24)) || job.bg0_3d);
        const uint32_t* const line3d = capture_uses_3d
            ? nds_gpu3d_capture_line(y) : nds_gpu3d_line(y);
                }
                return finish(front, second);
            };
            // Live tile views or scanline effects can disagree with the
            // captured raster. Reject the entire frame if they do.
            if (native_column && to_rgb32(sample(terrain, hud_x, y)) != camera->native[y * 256 + hud_x])
                return false;

            const int sx = hud_x + camera->dx;
            const int sy = y + camera->dy;
            const auto sample_row = [&](TextLine& row, int source_y) {
                const auto left = sample(row, sx, source_y);
                return camera->half_x ? blend(left, sample(row, sx + 1, source_y), 8, 8) : left;
            };
            const auto upper = sample_row(shifted, sy);
            dst[x] = to_rgb32(camera->half_y ? blend(upper, sample_row(next_row, sy + 1), 8, 8) : upper);
        }
    }
    return true;
}

bool matches_dungeon_scroll(const Unit& u, const NdsGpu2dDungeonMap& map) {
    return map.entries && (u.dispcnt & 0x800u) && (u.bgcnt[3] >> 14) == 1u &&
           u.bgx[3] == (map.scroll_x & 0x1FF) &&
           (u.bgy[3] & 0xFF) == (map.scroll_y & 0xFF);
}

void nds_gpu2d_capture_dungeon_raster(bool enabled) {
    g_capture_dungeon_raster = enabled;
}

bool nds_gpu2d_dungeon_scroll(int screen, uint16_t& x, uint16_t& y) {
    const auto& raster = g_dungeon_raster[g_front];
    const auto& u = raster.unit;
    if (raster.lines != 192 || raster.screen != static_cast<unsigned>(screen) ||
        !(u.dispcnt & 0x800u) || (u.bgcnt[3] >> 14) != 1u) return false;
    x = u.bgx[3];
    y = u.bgy[3];
    return true;
}

const uint32_t* nds_gpu2d_dungeon_camera_frame(int screen, uint16_t width,
    const NdsGpu2dDungeonMap& map, int16_t dx_q8, int16_t dy_q8) {
    const int engine_a_screen = (nds_powercontrol9() & 0x8000u) ? 0 : 1;
    if (screen != engine_a_screen || width < 256 || width > kMaxAdaptiveWidth ||
        width != nds_gpu3d_output_width() || g_adaptive_center_native || (!dx_q8 && !dy_q8) ||
        dx_q8 % 128 || dy_q8 % 128 || std::abs(dx_q8) > 12 * 256 || std::abs(dy_q8) > 12 * 256)
        return nullptr;
    drain_pool(NDS_GPU2D_FENCE_PRESENT);
    const auto& raster = g_dungeon_raster[g_front];
    if (raster.lines != 192 || raster.screen != static_cast<unsigned>(screen)) return nullptr;
    const Unit& u = raster.unit;
    const bool bg0_3d = (u.dispcnt & 0x108u) == 0x108u;
    if (!matches_dungeon_scroll(u, map) || !wide_2d_scene_supported(u, bg0_3d))
        return nullptr;
    const auto* vram = nds_vram_renderer_view(0);
    if (!vram) return nullptr;

    const DungeonCameraSample camera{nds_gpu2d_framebuffer(screen),
        dx_q8 >> 8, dy_q8 >> 8, (dx_q8 & 0x80) != 0, (dy_q8 & 0x80) != 0};
    static AdaptiveFrame midpoint;
    return composite_2d_wide_frame(u, raster.palette.data(), raster.oam.data(), *vram, width, (width - 256) / 2,
                                   midpoint, map.entries, bg0_3d, &camera)
        ? midpoint.data() : nullptr;
}

const uint32_t* nds_gpu2d_adaptive_framebuffer(int screen, uint16_t* width,
    NdsGpu2dScene scene, const NdsGpu2dDungeonMap* dungeon_map) {
    drain_pool(NDS_GPU2D_FENCE_PRESENT);
    const uint32_t* native = nds_gpu2d_framebuffer(screen);
    const bool engine_a_on_top = (nds_powercontrol9() & 0x8000u) != 0;
    const int engine = engine_a_on_top ? screen : (screen ^ 1);
    // Cleared so every early return below (native width, unsupported scene)
    // leaves the presenter on the CPU composite rather than re-reading last
    // frame's surfaces. Guarded on engine A: this function is called once per
            const int layout_w = std::max(top_width, bottom_width);
            if (layout_w != presentation.canvas_width) {
                presentation.canvas_width = layout_w;
                set_render_logical_size(presentation.renderers[0], layout_w, kScreenHeight * 2);
            }
