            (sky_dungeon || camera_interpolator.PreviousTick().mode == ActiveGameMode::DungeonOverlay29) &&
            (!camera_interpolator.HasTwoSnapshots() || previous_game_screen != sky_game_screen);
        // Insert at most one midpoint. Guest execution, input and audio run
        // only on real frames, and the queued audio still gates extra work.
        if (!dungeon_transition && interpolation_active && blend_cache.valid && !turbo_active &&
            !direct_present &&
            blend_cache.widths[0] == top_width &&
            blend_cache.widths[1] == bottom_width && audio_started &&
            audio_queue_count(audio, audio_queue) >
                kInterpolationAudioFloorFrames) {
            const uint32_t* midpoint[]{top_pixels, bottom_pixels};
            const uint32_t* camera_pixels = nullptr;
            bool camera_cut = false;
            if (dungeon_camera_enabled && camera_interpolator.HasTwoSnapshots() &&
                (sky_dungeon || camera_interpolator.PreviousTick().mode == ActiveGameMode::DungeonOverlay29)) {
                const auto camera_frame = camera_interpolator.EvaluateSubFrame(0.5f);
                camera_cut = camera_frame.camera_snapped;
                const int16_t dx = camera_frame.camera_subpixel_dx_q8;
                const int16_t dy = camera_frame.camera_subpixel_dy_q8;
                if (sky_dungeon && !camera_cut && (dx || dy) && !fps_meter_frame &&
