with log.open('wb') as out:
    proc = subprocess.Popen(cmd, env=env, stdout=out, stderr=out, cwd=scratch)
try:
    deadline = time.monotonic() + 15
    while True:
        try:
            conn = socket.create_connection(('127.0.0.1', port), timeout=1)
            break
        except OSError:
            if proc.poll() is not None or time.monotonic() > deadline:
                raise
            time.sleep(0.05)
    conn.settimeout(8)
    with conn, conn.makefile('rwb') as stream:
        def call(cmd, **fields):
            stream.write(json.dumps(dict(cmd=cmd, **fields)).encode() + b'\n')
            stream.flush()
            return json.loads(stream.readline())
        def key(key, down):
            assert call('frontend_input', action='key', key=key, down=down)['ok']
        def tap(name):
            key(name, True)
            time.sleep(0.1)
            key(name, False)
        def mem(addr, nbytes):
            return bytes.fromhex(call('read_mem', addr=addr, len=nbytes)['hex'])
        assert call('ping')['pong']
        tap('F2')
        time.sleep(0.35)
        ptr, = struct.unpack('<I', mem(0x0235353c, 4))
        assert ptr, f'could not load dungeon from slot {slot}'
        def camera():
            return struct.unpack('<hh', mem(ptr+0x1a224, 4))
        print(f'slot {slot} width preset {aspect} refresh {refresh}, start {camera()}', flush=True)
        def screenshot(tag):
            for screen in ('A', 'B'):
                fb = call('framebuffer', engine=screen)
                (scratch / f'{tag}{screen}.ppm').write_bytes(b'P6\n256 192\n255\n' + bytes.fromhex(fb['rgb']))
        screenshot('saved')
        for _ in range(3): tap("X")
        screenshot('after')
        motion = []
        for direction in ('Right', 'Down', 'Left', 'Up', 'Right', 'Up'):
            key(direction, True)
            for _ in range(12):
                time.sleep(0.04)
                motion.append(camera())
            key(direction, False)
            time.sleep(0.05)
        print(f'Observed {len(set(motion))} camera positions {motion[:18]}', flush=True)
        stats = call('frontend_stats')
        print({key: stats[key] for key in ('frames', 'synthetic_presents', 'real_presents')}, flush=True)
        call('frontend_exit')
        assert proc.wait(timeout=10) == 0
        report = log.read_text(errors='replace')
        summary = re.findall(r'.*dungeon_camera_presents=\d+', report)[-1]
        print(summary, flush=True)
        assert (int(summary.rsplit('=', 1)[1]) > 0) == (refresh == 1), summary
finally:
    if proc.poll() is None:
        proc.terminate()
        proc.wait(timeout=5)
    print(log, flush=True)

