                const bool paired_y = camera->half_y && object_taps_y == 2;
                const auto sample_objects = [&](int ty) {
                    const auto left = push_object(moved_objects[ty * 2 + (paired_x ? terrain_tap_x : 0)][x],
                                                  front, second);
