                        ? blend(left, push_object(moved_objects[ty * 2 + 1][x], front, second), 8, 8)
                        : left;
                };
                const auto upper = sample_objects(paired_y ? terrain_tap_y : 0);
                return object_taps_y == 2 && !paired_y ? blend(upper, sample_objects(1), 8, 8) : upper;'''+s[end:]
