            const auto upper = sample_row(shifted, sy, 0);
            dst[x] = to_rgb32(camera->half_y ? blend(upper, sample_row(next_row, sy + 1, 1), 8, 8) : upper);''')
p.write_text(s)
p=Path('third_party/ndsrecomp/runner/tests/gpu2d_window_test.cpp')
s=p.read_text().replace('        // Changing a tile seen only by a shifted tap cannot affect the midpoint.', '''        // In the first tap the opaque OBJ fully covers the red terrain.
        // The second tap exposes only green, so the edge must contain no red.
        offsets[0] = {1, 0};
        mid = nds_gpu2d_dungeon_camera_frame(1, width, map, 128, 0, &offsets);
        if (!mid || mid[left + 12] != to_rgb32(blend(blue, green, 8, 8))) return false;

        // Changing a tile seen only by a shifted tap cannot affect the midpoint.''')
p.write_text(s)
PY
